{"code": "import pytest
import impl


def test_basic_allow():
    """Request matching an ALLOW policy returns ALLOW."""
    request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_basic_deny():
    """Request matching a DENY policy returns DENY."""
    request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
    policies = [{"effect": "DENY", "principal": "user:alice", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_default_deny_no_match():
    """Request with no matching policies defaults to DENY."""
    request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:bob", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_default_deny_empty_policies():
    """Empty policies list defaults to DENY."""
    request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
    assert impl.authorize(request, []) == "DENY"


def test_deny_overrides_allow():
    """When both DENY and ALLOW match, DENY wins."""
    request = {"subject": "alice", "roles": ["contractor"], "action": "read", "resource": "docs/reports/Q1"}
    policies = [
        {"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "docs/reports/*"},
        {"effect": "DENY", "principal": "role:contractor", "action": "read", "resource": "docs/reports/*"}
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_deny_overrides_allow_regardless_of_order():
    """DENY overrides ALLOW even when listed later."""
    request = {"subject": "alice", "roles": ["contractor"], "action": "read", "resource": "docs/reports/Q1"}
    policies = [
        {"effect": "DENY", "principal": "role:contractor", "action": "read", "resource": "docs/reports/*"},
        {"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "docs/reports/*"}
    ]
    assert impl.authorize(request, policies) == "DENY"


def test_principal_wildcard():
    """Wildcard principal * matches any subject."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_user_match():
    """user:X principal matches when X equals request subject."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_role_match():
    """role:X principal matches when X is in request roles."""
    request = {"subject": "alice", "roles": ["admin"], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_principal_multiple_roles():
    """Request with multiple roles matches if any role matches principal."""
    request = {"subject": "alice", "roles": ["user", "admin"], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "role:admin", "action": "read", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_action_pattern_trailing_star():
    """Trailing * in action is a prefix match."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:Get*", "resource": "file"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_resource_pattern_trailing_star_strict():
    """Trailing * in resource requires strict prefix, doesn't skip characters."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "docs/reportsQ1"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "read", "resource": "docs/reports/*"}]
    assert impl.authorize(request, policies) == "DENY"


def test_pattern_non_final_asterisk_literal():
    """Non-final asterisk in pattern is literal, not wildcard."""
    request = {"subject": "alice", "roles": [], "action": "s3:GetObject", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "s3:*Object", "resource": "file"}]
    assert impl.authorize(request, policies) == "DENY"


def test_pattern_wildcard_matches_all():
    """* alone in action or resource matches everything."""
    request = {"subject": "alice", "roles": [], "action": "anything", "resource": "docs/anything"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "*", "resource": "*"}]
    assert impl.authorize(request, policies) == "ALLOW"


def test_case_sensitive_matching():
    """Pattern matching is case-sensitive."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "user:Alice", "action": "Read", "resource": "File"}]
    assert impl.authorize(request, policies) == "DENY"


def test_request_validation_missing_fields():
    """Missing required request fields raise ValueError."""
    request = {"subject": "alice", "action": "read", "resource": "file"}
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_request_validation_roles_not_list():
    """Request roles field must be a list."""
    request = {"subject": "alice", "roles": "admin", "action": "read", "resource": "file"}
    with pytest.raises(ValueError):
        impl.authorize(request, [])


def test_policy_validation_missing_fields():
    """Missing required policy fields raise ValueError."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
    policies = [{"effect": "ALLOW", "principal": "*", "action": "read"}]
    with pytest.raises(ValueError):
        impl.authorize(request, policies)


def test_policy_validation_invalid_effect():
    """Invalid effect value raises ValueError with value verbatim in message."""
    request = {"subject": "alice", "roles": [], "action": "read", "resource": "file"}
    policies = [{"effect": "Allow", "principal": "*", "action": "read", "resource": "file"}]
    with pytest.raises(ValueError) as exc_info:
        impl.authorize(request, policies)
    assert "Allow" in str(exc_info.value)


def test_request_not_mutated():
    """authorize() does not mutate the request dict."""
    request = {"subject": "alice", "roles": ["user"], "action": "read", "resource": "file"}
    request_copy = request.copy()
    policies = [{"effect": "ALLOW", "principal": "user:alice", "action": "read", "resource": "file"}]
    impl.authorize(request, policies)
    assert request == request_copy
"}
